function initAutocomplete(){address1Field=document.querySelector("#pa_address"),cityField=document.querySelector("#pa_city"),stateField=document.querySelector("#papa_state"),postalField=document.querySelector("#pa_zip"),autocomplete=new google.maps.places.Autocomplete(address1Field,{componentRestrictions:{country:["us"]},fields:["address_components","geometry"],types:["address"]}),autocomplete.addListener("place_changed",fillInAddress)}function fillInAddress(){const e=autocomplete.getPlace();let t="",o="",a="",l="";for(const s of e.address_components){const e=s.types[0];switch(console.log(e),console.log(s),e){case"street_number":t=`${s.long_name} ${t}`;break;case"route":t+=s.short_name;break;case"postal_code":o=`${s.long_name}${o}`;break;case"postal_code_suffix":o=`${o}-${s.long_name}`;break;case"administrative_area_level_1":a=s.short_name;break;case"locality":l=s.long_name}}address1Field.value=t,postalField.value=o,cityField.value=l,stateField.value=a,jQuery(stateField).change()}let autocomplete,address1Field,cityField,stateField,postalField;window.initAutocomplete=initAutocomplete;